// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // accept Ether so that c.withdrawAll()'s transfer back succeeds
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: a positive deposit that the fuzzer chooses
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance + address(c).balance + 1e30);

        // fund an arbitrary depositor and let anyone deposit via the payable fallback
        address depositor = address(uint160(uint256(keccak256(abi.encode(amount, block.number))))) ;
        vm.assume(depositor != address(c) && depositor != address(0));
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);

        // owner (this test contract, which deployed c) drains the contract
        vm.prank(address(this));
        c.withdrawAll();

        // general rule: after withdrawAll as owner, c holds no Ether
        assertTrue(address(c).balance == 0);
    }
}
